.switch-wrapper {
  display: flex;
  align-items: center;
  gap: var(--padding-m);
  cursor: pointer;
  user-select: none;
}

.switch {
  position: relative;
  width: 44px;
  height: 24px;
  appearance: none;
  cursor: pointer;
  background: transparent;
  border: none;
  padding: 0;
  margin: 0;
}

.switch::before {
  content: '';
  position: absolute;
  width: 100%;
  height: 100%;
  background-color: #d0d5dd;
  border-radius: 12px;
  transition: background-color 200ms ease;
}

.switch:checked::before {
  background-color: var(--button-background);
}

.switch-slider {
  position: absolute;
  width: 20px;
  height: 20px;
  background-color: white;
  border-radius: 10px;
  top: 2px;
  left: 2px;
  transition: left 200ms ease;
  pointer-events: none;
}

.switch:checked ~ .switch-slider {
  left: 22px;
}

.switch:focus {
  outline: 2px solid var(--button-background);
  outline-offset: 2px;
}

.switch-label {
  font-size: 14px;
  color: var(--text-primary);
  line-height: 1.5;
}

