import { useState } from 'react';
import { Switch } from '../components/Switch';
import { Button } from '../components/Button';
import './notification-settings.css';

export function NotificationSettings() {
  const [emailNotifications, setEmailNotifications] = useState(true);
  const [pushNotifications, setPushNotifications] = useState(true);
  const [saved, setSaved] = useState(false);

  const handleSave = () => {
    setSaved(true);
    setTimeout(() => setSaved(false), 3000);
  };

  return (
    <div className="notification-settings">
      <div className="notification-settings__container">
        <h1 className="notification-settings__title">Notification Settings</h1>

        <div className="notification-settings__group">
          <Switch
            label="Email Notifications"
            checked={emailNotifications}
            onChange={(e) => setEmailNotifications(e.target.checked)}
          />
          <p className="notification-settings__description">
            Receive email updates about your account activity
          </p>
        </div>

        <div className="notification-settings__group">
          <Switch
            label="Push Notifications"
            checked={pushNotifications}
            onChange={(e) => setPushNotifications(e.target.checked)}
          />
          <p className="notification-settings__description">
            Receive push notifications on your device
          </p>
        </div>

        <div className="notification-settings__actions">
          <Button Label="Save" onClick={handleSave} />
          {saved && (
            <div className="notification-settings__confirmation">
              ✓ Settings saved successfully
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

