import { useState } from 'react';
import { Field } from './Field';
import { Chip } from './Chip';
import { Button } from './Button';
import { Tag } from './Tag';
import './search-results-header.css';

export function SearchResultsHeader() {
  const [searchValue, setSearchValue] = useState('');
  const [activeFilter, setActiveFilter] = useState('today');

  const filters = [
    { id: 'today', label: 'Today', isNew: true },
    { id: 'week', label: 'This week', isNew: false },
    { id: 'month', label: 'This month', isNew: false },
  ];

  const handleFilterClick = (filterId) => {
    setActiveFilter(filterId);
  };

  return (
    <div className="search-header">
      <div className="search-header__input-group">
        <Field
          label="Search results"
          value={searchValue}
          onChange={(e) => setSearchValue(e.target.value)}
          placeholder="Search..."
        />
        <Button Label="Search" />
      </div>

      <div className="search-header__filters">
        {filters.map((filter) => (
          <div key={filter.id} className="search-header__filter-chip-wrapper">
            <Chip
              Label={filter.label}
              pressed={activeFilter === filter.id}
              onClick={() => handleFilterClick(filter.id)}
            />
            {filter.isNew && <Tag Label="New" Tone="Neutral" />}
          </div>
        ))}
      </div>
    </div>
  );
}

