import React, { useState } from 'react';
import { Search, X } from 'lucide-react';

export function SearchResultsHeader() {
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedFilter, setSelectedFilter] = useState('today');

  const filters = [
    { id: 'today', label: 'Today', isNew: true },
    { id: 'week', label: 'This week', isNew: false },
    { id: 'month', label: 'This month', isNew: false },
  ];

  return (
    <div className="w-full bg-white border-b border-gray-200">
      <div className="max-w-6xl mx-auto px-6 py-6 space-y-4">
        {/* Search Input and Button */}
        <div className="flex gap-3">
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search..."
              className="w-full pl-10 pr-4 py-2.5 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            />
            {searchQuery && (
              <button
                onClick={() => setSearchQuery('')}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
              >
                <X className="w-5 h-5" />
              </button>
            )}
          </div>
          <button className="px-6 py-2.5 bg-blue-600 text-white font-medium rounded-lg hover:bg-blue-700 active:bg-blue-800 transition-colors">
            Search
          </button>
        </div>

        {/* Filter Chips */}
        <div className="flex gap-2 flex-wrap">
          {filters.map((filter) => (
            <button
              key={filter.id}
              onClick={() => setSelectedFilter(filter.id)}
              className={`relative px-4 py-2 rounded-full font-medium transition-all ${
                selectedFilter === filter.id
                  ? 'bg-blue-100 text-blue-700 border border-blue-300'
                  : 'bg-gray-100 text-gray-700 border border-gray-200 hover:bg-gray-150'
              }`}
            >
              <span>{filter.label}</span>
              {filter.isNew && (
                <span className="absolute -top-2 -right-2 bg-red-500 text-white text-xs font-bold px-2 py-0.5 rounded-full">
                  New
                </span>
              )}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

// Demo component
export default function Demo() {
  return (
    <div className="min-h-screen bg-gray-50">
      <SearchResultsHeader />
      <div className="max-w-6xl mx-auto px-6 py-8">
        <p className="text-gray-600">Search results will appear below...</p>
      </div>
    </div>
  );
}

