.projects-empty-state {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 400px;
  padding: 40px;
  background-color: var(--surface-page);
}

.projects-empty-state__content {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
  text-align: center;
  max-width: 320px;
}

.projects-empty-state__illustration {
  width: 120px;
  height: 100px;
  color: var(--text-primary);
  opacity: 0.6;
}

.projects-empty-state__heading {
  margin: 0;
  font-size: 24px;
  font-weight: 600;
  line-height: 32px;
  color: var(--text-primary);
}

.projects-empty-state__description {
  margin: 0;
  font-size: 14px;
  line-height: 20px;
  color: var(--text-primary);
  opacity: 0.7;
}
